package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.*;import jakarta.servlet.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnExpression;
@RestController @ConditionalOnExpression("${medical.model-runtime.enabled:false} and ${medical.formal-invocation.enabled:false}")
public final class ModelRuntimeController {
 private final ApplicationSessionIdentity identities;private final ConnectionVerificationService connections;private final ModelEligibilityService eligibility;private final RuntimeGovernanceSchema schema;private final PermissionSchema json;
 public ModelRuntimeController(ApplicationSessionIdentity identities,ConnectionVerificationService connections,ModelEligibilityService eligibility,RuntimeGovernanceSchema schema,PermissionSchema json){this.identities=identities;this.connections=connections;this.eligibility=eligibility;this.schema=schema;this.json=json;}
 @PostMapping(value="/api/model-connection-verifications",consumes="application/json") @ResponseStatus(org.springframework.http.HttpStatus.CREATED) public JsonNode start(HttpServletRequest request,HttpServletResponse response,Authentication auth)throws Exception{String context=headers(request);var actor=identities.requireCurrent(request,auth);return envelope(schema.validate("ConnectionResult",connections.start(actor,context,key(request),body(request))),response);}
 @GetMapping("/api/model-connection-verification-operations") public JsonNode recover(HttpServletRequest request,HttpServletResponse response,Authentication auth)throws Exception{String context=headers(request);noBody(request);return envelope(schema.validate("ConnectionResult",connections.recover(identities.requireCurrent(request,auth),context,key(request))),response);}
 @PostMapping("/api/model-connection-verification-completions") public JsonNode complete(HttpServletRequest request,HttpServletResponse response,Authentication auth)throws Exception{String context=headers(request);noBody(request);return envelope(schema.validate("ConnectionPassed",connections.complete(identities.requireCurrent(request,auth),context,key(request))),response);}
 @PostMapping(value="/api/model-eligibilities",consumes="application/json") @ResponseStatus(org.springframework.http.HttpStatus.CREATED) public JsonNode enable(HttpServletRequest request,HttpServletResponse response,Authentication auth)throws Exception{String context=headers(request);var actor=identities.requireCurrent(request,auth);return envelope(schema.validate("ModelEnableReceipt",eligibility.enable(actor,context,key(request),body(request))),response);}
 @GetMapping("/api/model-eligibility-operations") public JsonNode recoverEligibility(HttpServletRequest request,HttpServletResponse response,Authentication auth)throws Exception{String context=headers(request);noBody(request);return envelope(schema.validate("ModelEnableRecovery",eligibility.recover(identities.requireCurrent(request,auth),context,key(request))),response);}
 private static String key(HttpServletRequest request){return SimulationInputArtifactController.one(request,"Idempotency-Key");}private static void noBody(HttpServletRequest r){if(r.getContentLengthLong()>0||r.getHeader("Transfer-Encoding")!=null)throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);}private static byte[] body(HttpServletRequest r)throws java.io.IOException{if(r.getContentLengthLong()>65536)throw new TenantAccessException(ErrorCode.FILE_TOO_LARGE);byte[] b=r.getInputStream().readNBytes(65537);if(b.length>65536)throw new TenantAccessException(ErrorCode.FILE_TOO_LARGE);return b;}
 private static String headers(HttpServletRequest r){if(r.getQueryString()!=null)throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);if(!"1.0.0".equals(SimulationInputArtifactController.one(r,"X-Schema-Version")))throw new SchemaRejection(ErrorCode.SCHEMA_UNSUPPORTED);String c=SimulationInputArtifactController.one(r,"X-Context-Revision");PermissionSchema.revision(c);return c;}
 private JsonNode envelope(JsonNode data,HttpServletResponse response){String id=java.util.UUID.randomUUID().toString();response.setHeader("Cache-Control","no-store");response.setHeader("X-Schema-Version","1.0.0");response.setHeader("X-Resource-Revision","1");response.setHeader("X-Request-Id",id);return json.tree(new InterfaceProtocol.Envelope("1.0.0",id,"1",data));}
 @ExceptionHandler(SchemaRejection.class) void invalid(SchemaRejection failure,HttpServletResponse response)throws java.io.IOException{new IdentityErrorResponseWriter().write(response,422,failure.code());}
 @ExceptionHandler(TenantAccessException.class) void denied(TenantAccessException failure,HttpServletResponse response)throws java.io.IOException{new IdentityErrorResponseWriter().write(response,status(failure.code()),failure.code());}
 static int status(ErrorCode code){return switch(code){case ACCESS_DENIED->403;case FILE_TOO_LARGE->413;case CONTEXT_CHANGED,SCOPE_STALE,IDEMPOTENCY_CONFLICT,REVISION_CONFLICT->409;case DEPENDENCY_UNAVAILABLE,MODEL_UNAVAILABLE,SECRET_UNAVAILABLE->503;default->422;};}
}
